public struct FfiConverterTypeRelayEngine: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = RelayEngine

    public static func lift(_ handle: UInt64) throws -> RelayEngine {
        return RelayEngine(unsafeFromHandle: handle)
    }

    public static func lower(_ value: RelayEngine) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> RelayEngine {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: RelayEngine, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
