public 
enum RelayError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    case InvalidCard(message: String
    )
    case KeyChanged(message: String
    )
    case NoSession(message: String
    )
    case Decrypt(message: String
    )
    case Malformed(message: String
    )
    case Unknown(message: String
    )
    case Storage(message: String
    )
    case Group(message: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension RelayError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeRelayError: FfiConverterRustBuffer {
    typealias SwiftType = RelayError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> RelayError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .InvalidCard(
            message: try FfiConverterString.read(from: &buf)
            )
        case 2: return .KeyChanged(
            message: try FfiConverterString.read(from: &buf)
            )
        case 3: return .NoSession(
            message: try FfiConverterString.read(from: &buf)
            )
        case 4: return .Decrypt(
            message: try FfiConverterString.read(from: &buf)
            )
        case 5: return .Malformed(
            message: try FfiConverterString.read(from: &buf)
            )
        case 6: return .Unknown(
            message: try FfiConverterString.read(from: &buf)
            )
        case 7: return .Storage(
            message: try FfiConverterString.read(from: &buf)
            )
        case 8: return .Group(
            message: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: RelayError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .InvalidCard(message):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .KeyChanged(message):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .NoSession(message):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Decrypt(message):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Malformed(message):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Unknown(message):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Storage(message):
            writeInt(&buf, Int32(7))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Group(message):
            writeInt(&buf, Int32(8))
            FfiConverterString.write(message, into: &buf)
            
        }
    }
}


